        AppLanguage.PORTUGUESE -> "Cookies de Terceiros"
        AppLanguage.SPANISH -> "Cookies de Terceros"
        AppLanguage.FRENCH -> "Cookies tiers"
        AppLanguage.GERMAN -> "Drittanbieter-Cookies"
        AppLanguage.RUSSIAN -> "Сторонние файлы cookie"
